// Generated by `eos scaffold e2e-node`. Dev deps: {{PM}} add -D @playwright/test @axe-core/playwright
// Script in package.json: "test:e2e": "playwright test". CI runs it when this file exists.
import { existsSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { defineConfig, devices } from "@playwright/test";

// Flaky tests quarantined with `eos quarantine add "<test title>"` (tests/quarantine.json) are skipped until
// their entry expires; then they run again and `eos check` fails CI until someone fixes or deletes them.
function quarantined(): RegExp | undefined {
  const today = new Date().toISOString().slice(0, 10);
  for (let d = resolve("."); ; d = dirname(d)) {
    const f = join(d, "tests", "quarantine.json");
    if (existsSync(f)) {
      const entries: { id: string; expires?: string }[] = JSON.parse(readFileSync(f, "utf8")).tests ?? [];
      const ids = entries
        .filter((e) => (e.expires ?? "") >= today)
        .map((e) => e.id.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
      return ids.length ? new RegExp(ids.join("|")) : undefined;
    }
    if (dirname(d) === d) return undefined;
  }
}

const baseURL = process.env.BASE_URL ?? "http://127.0.0.1:3000";

export default defineConfig({
  testDir: "./e2e",
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  // One retry on CI, only to record a trace; a test that passes on retry is reported as "flaky": quarantine
  // it or fix it, never raise retries to get green. Shards: --shard=1/4 plus the "blob" reporter, then
  // `playwright merge-reports`.
  retries: process.env.CI ? 1 : 0,
  grepInvert: quarantined(),
  reporter: process.env.CI ? "github" : "list",
  use: { baseURL, trace: "on-first-retry", screenshot: "only-on-failure" },
  projects: [{ name: "chromium", use: { ...devices["Desktop Chrome"] } }],
  webServer: process.env.BASE_URL
    ? undefined
    : { command: "{{PM}} run start", url: baseURL, reuseExistingServer: !process.env.CI, timeout: 120_000 },
});
